import XCTest

final class RepostTests: XCTestCase {
  func testRepostFirstFollowingPost() throws {
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    app.activate()
    sleep(2)
    let repost = app.buttons.matching(NSPredicate(format: "label CONTAINS[c] 'Repost'")).firstMatch
    XCTAssertTrue(repost.waitForExistence(timeout: 10))
    repost.tap()
    sleep(1)
    let confirm = app.buttons["Repost"].firstMatch
    XCTAssertTrue(confirm.waitForExistence(timeout: 5))
    confirm.tap()
    sleep(2)
    let shot = XCTAttachment(screenshot: app.screenshot())
    shot.lifetime = .keepAlways
    add(shot)
  }
}
EOF
